import React, { ReactElement, ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { ArrayField } from "@formily/core";
import {
  useField,
  observer,
  useFieldSchema,
  RecursionField,
  ReactFC,
  VoidField,
} from "@formily/react";
import cls from "classnames";
import {
  SortableContainer,
  SortableElement,
  SortableContainerProps,
  SortableElementProps,
} from "react-sortable-hoc";
import { ISchema } from "@formily/json-schema";
import { usePrefixCls } from "../__builtins__";
import { ArrayBase, ArrayBaseMixins } from "../ArrayBase";
import toArray from "rc-util/es/Children/toArray";

export interface IArrayItemsComponentProps
  extends React.PropsWithChildren<React.HTMLAttributes<HTMLDivElement>> {
  /**
   * 最大高度
   */
  maxHeight?: number;
  /**
   * 每一项之间的间距
   */
  itemGap?: number;
}

type ComposedArrayItems = React.FC<IArrayItemsComponentProps> &
  ArrayBaseMixins & {
    Item?: React.FC<React.HTMLAttributes<HTMLDivElement>>;
  };

const SortableItem: ReactFC<
  React.HTMLAttributes<HTMLDivElement> & SortableElementProps
> = SortableElement(
  (props: React.PropsWithChildren<React.HTMLAttributes<HTMLDivElement>>) => {
    const prefixCls = usePrefixCls("formily-array-items");
    return (
      <div {...props} className={cls(`${prefixCls}-item`, props.className)}>
        {props.children}
      </div>
    );
  }
) as any;

const SortableList: ReactFC<
  React.HTMLAttributes<HTMLDivElement> & SortableContainerProps
> = SortableContainer(
  (props: React.PropsWithChildren<React.HTMLAttributes<HTMLDivElement>>) => {
    const prefixCls = usePrefixCls("formily-array-items");
    return (
      <div {...props} className={cls(`${prefixCls}-sortable`, props.className)}>
        {props.children}
      </div>
    );
  }
) as any;

const isAdditionComponent = (schema: ISchema) =>
  schema["x-component"]?.indexOf("Addition") > -1;

const useAddition = () => {
  const schema = useFieldSchema();
  return schema.reduceProperties((addition, schema, key) => {
    if (isAdditionComponent(schema)) {
      return <RecursionField schema={schema} name={key} />;
    }
    return addition;
  }, null);
};

export const SchemaItems = observer((props: IArrayItemsComponentProps) => {
  const field = useField<ArrayField>();
  const prefixCls = usePrefixCls("formily-array-items");
  const schema = useFieldSchema();
  const addition = useAddition();
  const dataSource = Array.isArray(field.value) ? field.value : [];

  const { itemGap = 20, style = {}, maxHeight, ...rest } = props;
  const lastLength = useRef<number>(0);
  const endRef = useRef<HTMLDivElement>(null);

  if (maxHeight) {
    style.overflowY = "scroll";
    if (!style.maxHeight) {
      style.maxHeight = maxHeight;
    }
  }

  const canScrollToBottom =
    (style.overflowY === "scroll" || style.overflow === "scroll") &&
    (style.height || style.maxHeight);

  useEffect(() => {
    if (
      endRef.current &&
      canScrollToBottom &&
      dataSource.length > lastLength.current
    ) {
      endRef.current?.scrollIntoView({ behavior: "smooth" });
    }
    lastLength.current = dataSource.length;
  }, [dataSource.length, canScrollToBottom]);

  if (!schema) {
    throw new Error("can not found schema object");
  }
  return (
    <ArrayBase mode="schema">
      <div>
        <div
          {...rest}
          style={style}
          onChange={() => { }}
          className={cls(prefixCls, props.className)}
        >
          <SortableList
            useDragHandle
            lockAxis="y"
            helperClass={`${prefixCls}-sort-helper`}
            onSortEnd={({ oldIndex, newIndex }) => {
              field.move(oldIndex, newIndex);
            }}
          >
            {dataSource?.map((_, index) => {
              const items = Array.isArray(schema.items)
                ? schema.items[index] || schema.items[0]
                : schema.items;
              return (
                <ArrayBase.Item
                  key={index}
                  index={index}
                  record={() => field.value?.[index]}
                >
                  <SortableItem
                    style={itemGap ? { marginBottom: itemGap } : {}}
                    key={`item-${index}`}
                    index={index}
                  >
                    <RecursionField schema={items!} name={index} />
                  </SortableItem>
                </ArrayBase.Item>
              );
            })}
          </SortableList>
          <div ref={endRef} />
        </div>
        {addition}
      </div>
    </ArrayBase>
  );
});

SchemaItems.displayName = "ArraySchemaItems";

const useParseJSX = (children: ReactNode) => {
  return useMemo(() => {
    // 解析出所有的子 Item
    const childNodes = toArray(children, { keepEmpty: false });
    const itemsNodes: ReactNode[] = [];
    const additionNodes: ReactNode[] = [];
    childNodes.forEach((child) => {
      const childPropsComponent = (child as ReactElement)?.props?.component;
      // 对应 field.component 属性
      const [component] = childPropsComponent || [];
      switch (component?.displayName) {
        case "ArrayAddition":
          additionNodes.push(child);
          break;
        default:
          itemsNodes.push(child);
          break;
      }
    });
    // 这里只取第一个新增按钮和数组元素，多余的抛弃
    const [addition] = additionNodes;
    const [item] = itemsNodes;
    return { addition, item }
  }, [])
};

export const JSXItems = observer((props: IArrayItemsComponentProps) => {
  const field = useField<ArrayField>();
  // @ts-ignore
  const __arrayOperation = field.__arrayOperation
  const prefixCls = usePrefixCls("formily-array-items");
  const dataSource = Array.isArray(field.value) ? field.value : [];
  const { addition, item } = useParseJSX(props.children);
  const { itemGap = 0, style = {}, maxHeight, ...rest } = props;
  const endRef = useRef<HTMLDivElement>(null);
  const lastDataSourceLength = useRef<number>(dataSource.length);

  const increaseId = useRef<number>(dataSource.length);
  const keyIndexsLastDataSourceRef = useRef<number>(dataSource.length);
  const lastOperation = useRef<any>(__arrayOperation);
  const keyIndexsRef = useRef(dataSource.map((_, index) => `${index}_${Date.now().toString()}`));


  const scrollStyle = { ...style };
  if (maxHeight) {
    scrollStyle.overflowY = "auto";
    if (!scrollStyle.maxHeight) {
      scrollStyle.maxHeight = maxHeight;
    }
  }

  const canScrollToBottom =
    (scrollStyle.overflowY === "scroll" || scrollStyle.overflow === "scroll" || scrollStyle.overflowY === "auto" || scrollStyle.overflow === "auto") &&
    (scrollStyle.height || scrollStyle.maxHeight);

  useEffect(() => {
    if (canScrollToBottom && dataSource.length > lastDataSourceLength.current) {
      endRef.current?.scrollTo({
        behavior: "smooth",
        top: endRef.current.scrollHeight,
      });
    }
    lastDataSourceLength.current = dataSource.length;
  }, [dataSource.length, canScrollToBottom]);

  if (dataSource.length !== keyIndexsLastDataSourceRef.current || lastOperation.current !== __arrayOperation) {
    if (__arrayOperation) {
      switch (__arrayOperation.action) {
        case 'add':
          keyIndexsRef.current.splice(__arrayOperation.location, 0, `${increaseId.current++}_${Date.now().toString()}`)
          break;
        case 'remove':
          keyIndexsRef.current.splice(__arrayOperation.location, 1)
          break;
        case 'move':
          const fromItem = keyIndexsRef.current[__arrayOperation.location.old];
          keyIndexsRef.current.splice(__arrayOperation.location.old, 1);
          keyIndexsRef.current.splice(__arrayOperation.location.new, 0, fromItem);
          break;
        default:
          break;
      }
    }
    lastOperation.current = __arrayOperation;
    keyIndexsLastDataSourceRef.current = dataSource.length;
  }


  return (
    <ArrayBase mode="jsx">
      <div>
        <div
          {...rest}
          style={scrollStyle}
          onChange={() => { }}
          className={cls(prefixCls, props.className)}
          ref={endRef}
        >
          <SortableList
            useDragHandle
            lockAxis="y"
            helperClass={`${prefixCls}-sort-helper`}
            onSortEnd={({ oldIndex, newIndex }) => {
              // @ts-ignore
              field.__arrayOperation = { action: 'move', location: { old: oldIndex, new: newIndex } };
              field.move(oldIndex, newIndex);
            }}
          >
            {dataSource?.map((_, index) => (
              <ArrayBase.Item
                key={keyIndexsRef.current[index] || index}
                index={index}
                record={() => field.value?.[index]}
              >
                <SortableItem
                  style={itemGap ? { marginBottom: itemGap } : {}}
                  index={index}
                >
                  <VoidField name={index}>{item}</VoidField>
                </SortableItem>
              </ArrayBase.Item>
            ))}
          </SortableList>
        </div>
        {addition}
      </div>
    </ArrayBase>
  );
});

JSXItems.displayName = "ArrayJSXItems";

export const ArrayItems: ComposedArrayItems = (
  props: IArrayItemsComponentProps & {
    mode?: "jsx" | "schema";
  }
) => {
  const { mode, ...rest } = props;
  if (mode === "jsx") {
    return <JSXItems {...rest} />;
  } else {
    return <SchemaItems {...rest} />;
  }
};

ArrayItems.displayName = "ArrayItems";

ArrayItems.Item = (props) => {
  const prefixCls = usePrefixCls("formily-array-items");
  return (
    <div
      {...props}
      onChange={() => { }}
      className={cls(`${prefixCls}-item`, props.className)}
    >
      {props.children}
    </div>
  );
};

ArrayItems.Item.displayName = "ArrayItemsItem";

ArrayBase.mixin(ArrayItems);

export default ArrayItems;
